    std::vector<ParserCommit> m_commits;
    std::string m_input;              ///< 文本模式的输入副本
    const char *m_text = nullptr;     ///< m_input.c_str()
    std::size_t m_textPos = 0u;       ///< 文本模式的读写位置
    const Token *m_tokenArray = nullptr; ///< Token 数组（调用方所有）
